import{_ as t,o as s,c as a,a4 as n}from"./chunks/framework.BBs01uty.js";const h=JSON.parse('{"title":"Commit 阶段","description":"","frontmatter":{},"headers":[],"relativePath":"react/commit.md","filePath":"react/commit.md"}'),o={name:"react/commit.md"};function i(l,e,r,p,c,d){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="commit-阶段" tabindex="-1">Commit 阶段 <a class="header-anchor" href="#commit-阶段" aria-label="Permalink to &quot;Commit 阶段&quot;">​</a></h1><p>Render 阶段（beginWork + completeWork）可能会被中断和恢复，但 <strong>Commit 阶段一旦开始就会同步执行到底</strong>，不会被中断。这是因为 DOM 操作必须是原子性的——如果只更新了一半就中断，用户会看到不一致的 UI。</p><blockquote><p>前置知识：<a href="./reconciler.html">Reconciler 协调器</a> 中 completeWork 阶段的 flag 冒泡</p></blockquote><h2 id="整体流程" tabindex="-1">整体流程 <a class="header-anchor" href="#整体流程" aria-label="Permalink to &quot;整体流程&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;Render 阶段完成&lt;br/&gt;workInProgress 树构建完毕&quot;] --&gt; B{&quot;有副作用?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|无| C[&quot;直接切换 current 指针&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|有| D[&quot;BeforeMutation 阶段&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;Mutation 阶段&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[&quot;切换 current 指针&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G[&quot;Layout 阶段&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style D fill:#e1f5ff</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style E fill:#fff4e1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style G fill:#d4edda</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style F fill:#ffe1e1</span></span></code></pre></div><p>Commit 阶段包含三个子阶段，按顺序执行：<strong>BeforeMutation → Mutation → Layout</strong>。</p><hr><h2 id="递归模式-begin-与-complete" tabindex="-1">递归模式：begin 与 complete <a class="header-anchor" href="#递归模式-begin-与-complete" aria-label="Permalink to &quot;递归模式：begin 与 complete&quot;">​</a></h2><p>三个子阶段都遵循相同的递归模式，每个阶段分为 <strong>begin（递）</strong> 和 <strong>complete（归）</strong> 两步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>commitXXXEffects_begin（递）:</span></span>
<span class="line"><span>  向下遍历，找到最底层的有副作用的节点</span></span>
<span class="line"><span>  → 调用 commitXXXEffects_complete</span></span>
<span class="line"><span></span></span>
<span class="line"><span>commitXXXEffects_complete（归）:</span></span>
<span class="line"><span>  1. 对当前节点执行具体的副作用操作</span></span>
<span class="line"><span>  2. 有兄弟节点 → 返回兄弟，回到 begin 处理兄弟</span></span>
<span class="line"><span>  3. 无兄弟节点 → 回到父节点，对父节点执行副作用操作</span></span></code></pre></div><p>简单说就是：<strong>先一路向下找到叶子，从叶子开始处理，处理完一个看有没有兄弟，没有兄弟就回到父节点继续。</strong></p><hr><h2 id="beforemutation-阶段" tabindex="-1">BeforeMutation 阶段 <a class="header-anchor" href="#beforemutation-阶段" aria-label="Permalink to &quot;BeforeMutation 阶段&quot;">​</a></h2><p>这个阶段在 DOM 变更<strong>之前</strong>执行，所以它能拿到变更前的 DOM 状态。</p><p>主要做两件事：</p><ol><li><p><strong>调用 <code>getSnapshotBeforeUpdate</code></strong>（Class 组件）</p><ul><li>这个生命周期之所以叫 &quot;Before&quot;Snapshot，就是因为它在 DOM 变更前执行</li><li>可以读取变更前的 DOM 信息（如滚动位置），返回值会传给 <code>componentDidUpdate</code></li></ul></li><li><p><strong>调度 Passive Effect（useEffect）</strong></p><ul><li>useEffect 是异步的，这里只是把它调度到浏览器绘制之后执行</li><li>实际执行发生在 Layout 阶段之后</li></ul></li></ol><blockquote><p><strong>为什么需要这个阶段？</strong> 有些场景需要在 DOM 变更前读取信息（比如记录滚动位置），变更后再做对比。<code>getSnapshotBeforeUpdate</code> 就是为此设计的。</p></blockquote><hr><h2 id="mutation-阶段" tabindex="-1">Mutation 阶段 <a class="header-anchor" href="#mutation-阶段" aria-label="Permalink to &quot;Mutation 阶段&quot;">​</a></h2><p>这个阶段<strong>操作真实 DOM</strong>，是 Commit 阶段最核心的部分。</p><p>Mutation 阶段内部也遵循 begin（递）/ complete（归）的递归遍历模式。但要注意：<strong>递和归描述的是遍历顺序，而不是操作的执行时机。</strong> 实际的操作顺序是：<strong>先处理所有删除，再处理插入和更新。</strong></p><h3 id="删除-dom-元素" tabindex="-1">删除 DOM 元素 <a class="header-anchor" href="#删除-dom-元素" aria-label="Permalink to &quot;删除 DOM 元素&quot;">​</a></h3><p>删除操作优先执行。<code>fiber.deletions</code> 数组存储需要删除的节点。</p><p>实际操作比想象中复杂：需要递归执行子树的 unmount 逻辑，包括 Class 组件的 <code>componentWillUnmount</code> 和函数组件的 <code>useEffect</code> 清理函数（destroy）。<strong>子节点的 unmount 先于父节点</strong>——先清理子树，再处理父节点。</p><h3 id="移动-插入-更新-dom-元素" tabindex="-1">移动/插入/更新 DOM 元素 <a class="header-anchor" href="#移动-插入-更新-dom-元素" aria-label="Permalink to &quot;移动/插入/更新 DOM 元素&quot;">​</a></h3><p>删除完成后，从叶子节点向上处理：</p><ol><li><strong>移动/插入</strong>：找到父 DOM 节点和参考节点（before），将新 DOM 插入到 before 之前</li><li><strong>更新</strong>：<code>fiber.updateQueue</code> 中记录了需要更新的属性（由 render 阶段 completeWork 的 diffProperties 生成），在这里统一应用到 DOM 上</li><li><strong>置空 ref</strong>：仅在 mount 阶段或 ref 发生变化时执行</li></ol><h3 id="为什么先删除再插入" tabindex="-1">为什么先删除再插入？ <a class="header-anchor" href="#为什么先删除再插入" aria-label="Permalink to &quot;为什么先删除再插入？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    A (需要更新)</span></span>
<span class="line"><span>   / \\</span></span>
<span class="line"><span>  B   C (需要删除)</span></span>
<span class="line"><span> /</span></span>
<span class="line"><span>D (需要插入)</span></span></code></pre></div><p>以上面的树为例：C 需要从 A 的子节点中删除，D 需要作为 B 的新子节点插入。</p><p>React 选择先统一处理所有删除，再处理插入和更新。这样做的好处是<strong>避免 DOM 操作之间的引用冲突</strong>——插入操作需要指定参考节点（insertBefore 的 before 参数），如果先插入再删除，参考节点可能已经被移动或删除，导致插入位置错误。</p><blockquote><p>遍历顺序上，begin 阶段从根向下走（A → B → D → B → C），complete 阶段从叶子向上回（D → B → C → B → A）。删除和插入操作都挂载在这个遍历过程上，但执行的先后顺序是：先把遍历过程中遇到的删除全部处理完，再处理插入和更新。</p></blockquote><hr><h2 id="fiber-tree-切换" tabindex="-1">Fiber Tree 切换 <a class="header-anchor" href="#fiber-tree-切换" aria-label="Permalink to &quot;Fiber Tree 切换&quot;">​</a></h2><p>Mutation 完成后、Layout 开始前，执行 current 指针的切换：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">root.current </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> workInProgress;</span></span></code></pre></div><p><strong>为什么在这个时机切换？</strong> 这是为了 Class 组件生命周期的正确性：</p><ul><li><code>componentWillUnmount</code>（Mutation 阶段执行）→ 此时 current 还指向<strong>旧的</strong> Fiber 树（UI 中对应的树）</li><li><code>componentDidMount</code> / <code>componentDidUpdate</code>（Layout 阶段执行）→ 此时 current 已指向<strong>新的</strong> Fiber 树</li></ul><p>如果切换时机不对，生命周期函数中拿到的 current 就是错的。</p><hr><h2 id="layout-阶段" tabindex="-1">Layout 阶段 <a class="header-anchor" href="#layout-阶段" aria-label="Permalink to &quot;Layout 阶段&quot;">​</a></h2><p>这个阶段在 DOM 变更<strong>之后</strong>执行，所有 DOM 操作已经完成。</p><ol><li><strong>处理 OffscreenComponent 逻辑</strong>（递阶段）： <ul><li>向下遍历时，根据 Offscreen 的隐藏/可见状态逐层传递标记（<code>offscreenSubtreeIsHidden</code> / <code>offscreenSubtreeWasHidden</code>）</li><li>隐藏子树 → 跳过归阶段的 layout effects（组件不可见，执行无意义）</li><li>从隐藏变为可见 → 走 reappear 流程，重新挂载 effects（<code>componentDidMount</code>、attach ref、全部 <code>useLayoutEffect</code>）</li><li>一直可见 → 正常遍历</li><li>本质是一个<strong>状态分发器</strong>，为归阶段的每个节点决定该走哪条处理路径</li></ul></li><li><strong>根据 fiberNode.tag 执行不同逻辑</strong>（归阶段）： <ul><li>函数组件：执行 <code>useLayoutEffect</code> 的 create 函数</li><li>Class 组件：执行 <code>componentDidMount</code> / <code>componentDidUpdate</code></li><li>执行 <code>this.setState</code> 的第二个参数（回调函数）</li><li>执行 <code>ReactDOM.render</code> 的第三个参数（回调函数）</li></ul></li><li><strong>设置 ref</strong>（mount 阶段或 ref 发生变化时）</li></ol><blockquote><p><strong>useLayoutEffect vs useEffect 的关键区别：</strong></p><table tabindex="0"><thead><tr><th></th><th>useLayoutEffect</th><th>useEffect</th></tr></thead><tbody><tr><td>执行时机</td><td>Layout 阶段，<strong>同步</strong>执行</td><td>浏览器绘制之后，<strong>异步</strong>调度</td></tr><tr><td>是否阻塞渲染</td><td>是，JS 同步代码会阻塞浏览器渲染</td><td>否</td></tr><tr><td>适用场景</td><td>需要在浏览器绘制前同步读取/修改 DOM</td><td>大多数副作用场景</td></tr></tbody></table><p>简单记忆：<strong>useLayoutEffect 在 Layout 阶段同步执行，useEffect 在 Layout 阶段之后异步执行。</strong></p></blockquote><hr><h2 id="effects-list-→-subtree-flags-的演进" tabindex="-1">Effects List → Subtree Flags 的演进 <a class="header-anchor" href="#effects-list-→-subtree-flags-的演进" aria-label="Permalink to &quot;Effects List → Subtree Flags 的演进&quot;">​</a></h2><h3 id="v18-之前-effects-list" tabindex="-1">v18 之前：Effects List <a class="header-anchor" href="#v18-之前-effects-list" aria-label="Permalink to &quot;v18 之前：Effects List&quot;">​</a></h3><p>React 使用一个<strong>单向链表</strong>（Effects List）存储所有带副作用的 Fiber 节点。commit 阶段只需遍历这个链表，跳过没有副作用的节点。</p><p>看起来性能更好（只遍历有副作用的节点），但 React 在 v18 改用了 subtreeFlags。</p><h3 id="v18-之后-subtree-flags" tabindex="-1">v18 之后：Subtree Flags <a class="header-anchor" href="#v18-之后-subtree-flags" aria-label="Permalink to &quot;v18 之后：Subtree Flags&quot;">​</a></h3><p>每个 Fiber 节点通过 <code>subtreeFlags</code> 记录其子树中是否存在某种类型的副作用。commit 阶段需要<strong>遍历所有节点</strong>来检查 flags。</p><p><strong>为什么要改成更&quot;慢&quot;的方式？</strong></p><p>Suspense 的边界情况：如果子孙组件同时存在同步和异步组件，旧版本会先渲染 fallback 并显示同步组件（只是将异步组件 CSS 设为 <code>display:none</code>）。这不符合 Suspense 的设计理念——同步组件也不应该参与渲染。</p><p>Effects List 只能遍历到有副作用的节点，<strong>无法精确控制子树中哪些组件不参与渲染</strong>。改用 subtreeFlags 后，需要遍历所有组件，这样才能在 Suspense 边界处做出更精细的控制。</p><hr><blockquote><p>Commit 阶段将 Render 阶段的计算结果落地为真实 DOM 操作。想了解状态更新是如何触发整个流程的，见 <a href="./state-update.html">状态更新流程</a>。</p></blockquote>`,56)])])}const g=t(o,[["render",i]]);export{h as __pageData,g as default};
